appearances.css:
.dm{gap:4px}
.top{display:flex;flex-wrap:wrap;gap:4px 1px;padding:4px 5px;align-items:flex-start;border-radius:3px}
.top>.ctl{flex:0 0 58px;width:58px;min-width:0;justify-items:center;gap:0}
.ctl label{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:0;font-size:8px;letter-spacing:-.02em;text-transform:none;line-height:1.15;text-align:center;max-width:100%}
.ctl label output{font-size:8px;line-height:1.1;letter-spacing:0;white-space:nowrap}
.ctl .kn{order:-1;width:28px!important;height:28px!important;justify-self:center!important}
.ctl .kn svg{width:100%;height:100%}
.btns{flex:1 1 auto;margin-left:auto;align-self:center;gap:4px;flex-wrap:wrap;justify-content:flex-end}
button{font-size:10px;padding:5px 8px;min-height:26px;border-radius:3px}
.btns label{font-size:9px!important;gap:3px!important}
select{font-size:10px;padding:4px 3px;min-height:26px;border-radius:3px}
.link{padding:3px 6px;gap:2px 8px;font-size:9px;border-radius:3px}
.link:has(>.muted:only-child){display:none}
.link .ctl{display:grid;grid-auto-flow:row;justify-items:center;gap:0;min-width:46px}
.link .ctl .kn{width:24px!important;height:24px!important}
.link label.muted{font-size:9px}
.empty{padding:5px 8px;line-height:1.3;font-size:9px;border-radius:3px}
.tg{gap:3px}
.tg h3{font-size:11px;gap:6px}
.tg h3 small{font-size:9px}
.lane{padding:4px 5px;gap:4px;border-radius:3px}
.lhead{margin-bottom:2px}
.lhead b{font-size:11px}
.lhead button{min-height:22px;padding:1px 6px}
.prow{min-height:18px;gap:4px;grid-template-columns:16px 8px minmax(50px,1fr) minmax(60px,1.3fr) 34px 40px}
.prow output,.prow .live{font-size:9px}
.plot{min-height:56px}
.cap{font-size:9px;margin-top:2px}
.prow{min-height:16px;font-size:10px}
.prow input[type=checkbox]{width:12px;height:12px}
.prow input[type=range]{height:12px}
.lane{align-items:start}
